import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry schema registration', () => {
  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names a wrong-typed top-level property from an Ajv dataPath error', async () => {
    const validate = Object.assign(() => false, {
      errors: [{keyword: 'type', dataPath: '.unit', params: {type: 'string'}}],
    });
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validate as ReturnType<Ajv['compile']>);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {unit: {type: 'string'}}},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {unit: 42});
    compile.mockRestore();

    expect(response.result).toBe('/unit must be string');
  });

  // specs/hal-engine-tool-input-validation/spec.md#4
  it('reports every failing field path and constraint for one invalid call', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, unit: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {unit: 42});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/\/location is required; \/unit must be string/),
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#2
  it('escapes a required property name in the reported JSON Pointer path', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {'account/id': {type: 'string'}},
          required: ['account/id'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: '/account~1id is required',
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#8
  it('rejects an invalid static schema before registering the named tool', () => {
    const registry = new ToolRegistry();

    let errorMessage = '';
    try {
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      );
    } catch (error) {
      errorMessage = (error as Error).message;
    }

    expect({errorMessage, registered: registry.has('broken_weather')}).toEqual({
      errorMessage: expect.stringMatching(/broken_weather/),
      registered: false,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#10
  it('validates each resolved schema and reuses a validator for the same schema object', async () => {
    const registry = new ToolRegistry();
    const firstSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const secondSchema = {type: 'object', properties: {zip: {type: 'string'}}, required: ['zip']};
    let schema: ToolDefinition['inputSchema'] = firstSchema;
    let executorCalls = 0;
    registry.register(
      () => ({name: 'lookup', description: 'Lookup', inputSchema: schema}),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const first = await registry.execute('lookup', {});
    schema = secondSchema;
    const second = await registry.execute('lookup', {});
    const third = await registry.execute('lookup', {zip: '12345'});

    const calls = compile.mock.calls;
    const compilationCount = calls.length;
    expect({
      first: first.result,
      second: second.result,
      third: third.result,
      executorCalls,
      compiled: compilationCount,
    }).toEqual({
      first: expect.stringMatching(/location.*required|required.*location/),
      second: expect.stringMatching(/zip.*required|required.*zip/),
      third: 'ok',
      executorCalls: 1,
      compiled: 2,
    });
    compile.mockRestore();
  });
});

import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true} as ConstructorParameters<
    typeof Ajv
  >[0]);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    try {
      const validate = this.ajv.compile(schema);
      this.validators.set(schema, validate);
      return validate;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}`, {cause: error});
    }
  }

  private describeValidationError(error: ErrorObject): string {
    const instancePath = 'instancePath' in error ? error.instancePath : undefined;
    const dataPath = 'dataPath' in error ? error.dataPath : undefined;
    const legacyPath =
      typeof dataPath === 'string'
        ? dataPath
            .replace(/^\./, '/')
            .replace(/\./g, '/')
            .replace(/\[(\d+)\]/g, '/$1')
        : undefined;
    const path = (typeof instancePath === 'string' && instancePath) || legacyPath || '/';
    const params = error.params as Record<string, unknown>;
    if (error.keyword === 'required') {
      const property = String(params.missingProperty).replace(/~/g, '~0').replace(/\//g, '~1');
      return `${path === '/' ? '' : path}/${property} is required`;
    }
    if (error.keyword === 'type') return `${path} must be ${String(params.type)}`;
    return `${path} violates ${error.keyword}`;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      validate = this.compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input as specified in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate =
      tool.validate ?? this.compileSchema(name, this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) {
      const failures = (validate.errors ?? []).map(error => this.describeValidationError(error));
      const result = failures.join('; ');
      log.warn('tool', 'input rejected', {name, failures: result});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

